'use strict';const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),assert=require('node:assert/strict');const base=path.resolve(__dirname,'../../../.artifacts/deep-audit-question-delivery'),out=path.join(base,'producer-reconstruction-v2');assert.ok(!fs.existsSync(out));fs.mkdirSync(out);const hash=s=>crypto.createHash('sha256').update(s).digest('hex'),proofs=[];
for(const label of ['candidate-v1','candidate-v2']){const s=fs.readFileSync(path.join(base,label,'producer.mjs'),'utf8'),h=JSON.parse(fs.readFileSync(path.join(base,label,'hashes.json'))),r=s.replace(/(export const QUESTION_DELIVERY_SHA256 = ')[^']+(')/,`$1${h.question.output}$2`).replace(/(export const GATEWAY_DELIVERY_SHA256 = ')[^']+(')/,`$1${h.gateway.output}$2`);fs.writeFileSync(path.join(out,label+'.mjs'),r,{flag:'wx'});proofs.push({label,operation:'only fill generated SHA constants from contemporaneous hashes.json',source:hash(s),restored:hash(r)});}
const one=fs.readFileSync(path.join(out,'candidate-v1.mjs'),'utf8'),two=fs.readFileSync(path.join(base,'candidate-v2/producer.mjs'),'utf8'),marker='export async function publishQuestionDelivery(prepared) {';assert.equal(one.split(marker).length,2);assert.equal(two.split(marker).length,2);const combined=one.slice(0,one.indexOf(marker))+two.slice(two.indexOf(marker));fs.writeFileSync(path.join(out,'publisher-repaired.mjs'),combined,{flag:'wx'});proofs.push({label:'publisher-repaired',operation:'candidate-v1 generated constants plus exact candidate-v2 publication function, no generated-client change',restored:hash(combined)});
fs.writeFileSync(path.join(out,'proofs.json'),JSON.stringify(proofs,null,2));console.log(JSON.stringify(proofs));